async function loadAssetDashboard(){
 adData.value={assets:[],racks:[],placements:[],relations:[],canvases:[]};
 adSources.value={assets:'denied',racks:'denied',placements:'denied',relations:'denied',canvases:'denied'};
 const register=access.value['asset-register']?.read,rackRead=access.value['server-racks']?.read,modelRead=access.value['asset-modelling']?.read;
 const jobs=[['assets',register?'assets':rackRead||modelRead?'catalog':null],['racks',rackRead?'racks':null],['placements',rackRead?'placements':null],['relations',modelRead?'relations':null],['canvases',modelRead?'canvases':null],['main',modelRead?'diagram':null]].filter(([,endpoint])=>endpoint);
 const results=await Promise.allSettled(jobs.map(([,endpoint])=>api(endpoint)));
 let main=null,canvasList=[];
 results.forEach((result,index)=>{const [key]=jobs[index];if(result.status==='rejected'){if(key!=='main')adSources.value[key]='error';return;}if(key==='main')main=result.value;else if(key==='canvases'){canvasList=result.value;adSources.value.canvases='ready';}else {adData.value[key]=result.value;adSources.value[key]=key==='assets'&&!register?'catalog':'ready';}});
 if(modelRead){
  const snapshots=main?[{id:'main',name:'Kanvas utama',nodes:main.nodes,available:true}]:[{id:'main',name:'Kanvas utama',nodes:[],available:false}];
  const others=canvasList.filter(c=>c.id!=='main');
  for(let offset=0;offset<others.length;offset+=4){const batch=others.slice(offset,offset+4),loaded=await Promise.allSettled(batch.map(c=>api('canvases/'+c.id)));loaded.forEach((result,index)=>snapshots.push({...batch[index],nodes:result.status==='fulfilled'?result.value.nodes:[],available:result.status==='fulfilled'}));}
  adData.value.canvases=snapshots;if(adSources.value.canvases!=='ready'||snapshots.some(c=>!c.available))adSources.value.canvases='partial';
 }
 if(!adFullAssets.value){adFilters.value.owner='';adFilters.value.risk='';adFilters.value.renewal='';}
 message.value=Object.values(adSources.value).some(value=>['error','partial'].includes(value))?'Sebagian data dashboard belum dapat dimuat. Gunakan Muat ulang untuk mencoba kembali.':'';
}
