 const content=format==='json'?JSON.stringify(snapshot,null,2):'\uFEFF'+[['Asset ID','Tag','Name','Type','Status','Owner','Location','CIA risk','Renewal'],...adAssets.value.map(a=>[a.id,a.tag,a.name,a.type,a.status,a.owner,adLocation(a),assessmentResult(a.assetAssessment)?.level||'',a.renewalDate])].map(row=>row.map(quote).join(',')).join('\r\n');
