async function api(path,method='GET',body){const r=await fetch('/api/asset-management/'+path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});if(r.status===204)return;const data=await r.json();if(!r.ok)throw Error(data.error||'Permintaan gagal.');return data;}
async function load(){
 if(busy.value)return;busy.value=true;
 try{
  const r=await fetch('/api/auth/me');if(!r.ok)throw Error('Sesi berakhir.');const user=await r.json();vendorAccess.value=user.role==='admin'||Boolean(user.actions?.['tprm-register']?.read);riskAccess.value=user.role==='admin'||Boolean(user.actions?.['risk-management']?.read);
  access.value=user.role==='admin'?Object.fromEntries(assetModuleKeys.map(k=>[k,{read:true,create:true,update:true,delete:true}])):{...user.actions};
  access.value['asset-dashboard']={read:assetModuleKeys.some(key=>access.value[key]?.read)};
  if(!access.value[view.value]?.read)throw Error('Akses modul tidak tersedia.');
  if(view.value==='asset-dashboard')await loadAssetDashboard();
  else if(view.value==='server-racks'){
   const results=await Promise.allSettled([api('racks'),api('placements'),api('catalog'),api('photos')]);
   if(results[0].status==='rejected')throw results[0].reason;
   racks.value=results[0].value;
   if(!racks.value.some(r=>r.id===selectedRack.value))selectedRack.value=racks.value[0]?.id||'';
   if(results[1].status==='rejected'){placements.value=[];throw results[1].reason;}
   placements.value=results[1].value;
   assets.value=results[2].status==='fulfilled'?results[2].value:[];
   photoCatalog.value=results[3].status==='fulfilled'?results[3].value:{assets:[],racks:[]};failedPhotos.value=[];
   if(results[3].status==='rejected')message.value='Data rak berhasil dimuat. Foto belum tersedia; periksa atau restart backend terbaru.';
   else if(results[2].status==='rejected')message.value='Data rak berhasil dimuat. Katalog aset belum dapat dimuat.';
  }else if(view.value==='asset-register'){const results=await Promise.allSettled([api('assets'),api('photos'),riskAccess.value?api('risk-catalog'):Promise.resolve([]),vendorAccess.value?api('vendor-catalog'):Promise.resolve([])]);if(results[0].status==='rejected')throw results[0].reason;assets.value=results[0].value;riskCatalog.value=results[2].status==='fulfilled'?results[2].value:[];riskCatalogAvailable.value=riskAccess.value&&results[2].status==='fulfilled';managedVendors.value=results[3].status==='fulfilled'?results[3].value:[];vendorCatalogAvailable.value=vendorAccess.value&&results[3].status==='fulfilled';photoCatalog.value=results[1].status==='fulfilled'?results[1].value:{assets:[],racks:[]};failedPhotos.value=[];if(results[1].status==='rejected')message.value='Data aset berhasil dimuat. Foto belum dapat dimuat.';if(registerTab.value==='reminder')reminderSettings.value=await api('reminder-settings');}
  else{const results=await Promise.all([api('catalog'),api('relations'),api(canvasReadPath()),api('canvases')]);assets.value=results[0];relations.value=results[1];canvases.value=results[3].length?results[3]:[{id:'main',name:'Kanvas utama'}];if(!diagramDirty.value){diagramLayout.value=results[2].nodes;diagramVersion.value=results[2].version;}}
 }catch(e){message.value=e.message;}finally{busy.value=false;}
}
