const graphNodes=computed(()=>{const ids=new Set([...(activeCanvas.value==='main'?relations.value.flatMap(r=>[r.source_id,r.target_id]):[]),...diagramLayout.value.map(n=>n.id)]);if(activeCanvas.value==='main'&&selectedAsset.value)ids.add(selectedAsset.value);return assets.value.filter(a=>ids.has(a.id)).map((a,i)=>({...a,...(diagramLayout.value.find(n=>n.id===a.id)||{x:60+(i%4)*245,y:60+Math.floor(i/4)*130})}));});
