function diagramEdgeGeometry(r){
 const pair=[r.source_id,r.target_id].sort(),first=point(pair[0]),last=point(pair[1]);
 const siblings=relations.value.filter(e=>[e.source_id,e.target_id].sort().join('|')===pair.join('|')).slice().sort((a,b)=>[a.source_id,a.target_id,a.type,a.id].join('|').localeCompare([b.source_id,b.target_id,b.type,b.id].join('|')));
 const lane=siblings.findIndex(e=>e.id===r.id)-(siblings.length-1)/2,offset=lane*64;
 const dx=last.x-first.x,dy=last.y-first.y,length=Math.hypot(dx,dy)||1,nx=-dy/length,ny=(dx||(!dy?1:0))/length;
 const a=point(r.source_id),b=point(r.target_id),ac={x:a.x+95,y:a.y+29},bc={x:b.x+95,y:b.y+29};
 const control={x:(ac.x+bc.x)/2+nx*offset,y:(ac.y+bc.y)/2+ny*offset};
 const boundary=(center,towards,fallback)=>{let vx=towards.x-center.x,vy=towards.y-center.y;if(!vx&&!vy){vx=fallback.x-center.x;vy=fallback.y-center.y;}if(!vx&&!vy)vx=1;const scale=1/Math.max(Math.abs(vx)/97,Math.abs(vy)/31);return {x:center.x+vx*scale,y:center.y+vy*scale};};
 const source=boundary(ac,control,bc),target=boundary(bc,control,ac);
 return {path:`M${source.x},${source.y} Q${control.x},${control.y} ${target.x},${target.y}`,labelX:(source.x+2*control.x+target.x)/4+nx*10,labelY:(source.y+2*control.y+target.y)/4+ny*10};
}
function diagramEdgePath(r){return diagramEdgeGeometry(r).path;}

function diagramImage(){
 const source=diagramSvg.value;if(!source||!graphNodes.value.length)throw Error('Tambahkan aset ke kanvas sebelum export gambar.');
 const groups=[...source.querySelectorAll('[data-diagram-asset],[data-diagram-relation]')];
 const boxes=groups.map(g=>g.getBBox());const left=Math.min(...boxes.map(b=>b.x))-40,top=Math.min(...boxes.map(b=>b.y))-40;
 const width=Math.ceil(Math.max(...boxes.map(b=>b.x+b.width))-left+40),height=Math.ceil(Math.max(...boxes.map(b=>b.y+b.height))-top+40);
 const clone=source.cloneNode(true),originals=[source,...source.querySelectorAll('*')],copies=[clone,...clone.querySelectorAll('*')];
 const properties=['fill','stroke','stroke-width','stroke-linejoin','stroke-linecap','stroke-dasharray','font-family','font-size','font-weight','paint-order','opacity'];
 originals.forEach((el,i)=>{const style=getComputedStyle(el);copies[i].removeAttribute('style');for(const property of properties)copies[i].style.setProperty(property,style.getPropertyValue(property));copies[i].removeAttribute('tabindex');copies[i].removeAttribute('role');});
 clone.querySelectorAll('.asset-connection-port').forEach(el=>el.remove());
 clone.querySelectorAll(':scope > path').forEach(el=>el.remove());
 clone.querySelectorAll('[marker-end]').forEach(el=>el.setAttribute('marker-end','url(#assetArrow)'));
 clone.querySelectorAll(':scope > rect').forEach(el=>el.remove());
 const exportBackground=getComputedStyle(document.body).getPropertyValue('--white').trim()||'#ffffff';
 const background=document.createElementNS('http://www.w3.org/2000/svg','rect');for(const [key,value] of Object.entries({x:left,y:top,width,height,fill:exportBackground}))background.setAttribute(key,String(value));clone.insertBefore(background,clone.firstChild);
 clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.setAttribute('viewBox',`${left} ${top} ${width} ${height}`);clone.setAttribute('width',String(width));clone.setAttribute('height',String(height));clone.removeAttribute('class');clone.removeAttribute('style');
 return {svg:new XMLSerializer().serializeToString(clone),width,height};
}
async function exportDiagramImage(format='png'){
 if(busy.value||diagramExporting.value)return;diagramExporting.value=true;message.value='';let imageUrl;
 try{await nextTick();const image=diagramImage();let blob;
 if(format==='svg'){blob=new Blob([image.svg],{type:'image/svg+xml;charset=utf-8'});}else{
 const scale=Math.min(2,8192/image.width,8192/image.height,Math.sqrt(16000000/(image.width*image.height)));
 const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));
 const context=canvas.getContext('2d');if(!context)throw Error('Browser tidak dapat membuat gambar. Gunakan export SVG.');
 imageUrl=URL.createObjectURL(new Blob([image.svg],{type:'image/svg+xml;charset=utf-8'}));const drawing=new Image();await new Promise((resolve,reject)=>{drawing.onload=resolve;drawing.onerror=()=>reject(Error('Gambar gagal dibuat. Gunakan export SVG.'));drawing.src=imageUrl;});
 context.fillStyle='#ffffff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(drawing,0,0,canvas.width,canvas.height);
 blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('Gambar gagal dibuat. Gunakan export SVG.');
 }
 const url=URL.createObjectURL(blob),link=document.createElement('a'),name=canvases.value.find(c=>c.id===activeCanvas.value)?.name||'asset-canvas';link.href=url;link.download=name.replace(/[^a-zA-Z0-9_-]+/g,'-').slice(0,100)+'.'+format;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
 message.value=diagramDirty.value?'Gambar berhasil diexport. Perubahan diagram belum disimpan ke server.':'Gambar berhasil diexport.';
 }catch(e){message.value=e.message;}finally{if(imageUrl)URL.revokeObjectURL(imageUrl);diagramExporting.value=false;}
}
