function saveCanvasDetails(){const data={...canvasEditor.value};perform(async()=>{const result=await api('canvases'+(data.id?'/'+data.id:''),data.id?'PUT':'POST',data);if(data.id){diagramVersion.value=result.version;}else{activeCanvas.value=result.id;diagramLayout.value=[];diagramVersion.value=result.version;diagramDirty.value=false;selectedAsset.value='';}closeModal(true);});}
async function changeCanvas(id){if(busy.value||id===activeCanvas.value)return;pendingCanvas.value=id;if(diagramDirty.value){showModal('canvas-switch');return;}await applyCanvasSwitch(false);}
async function applyCanvasSwitch(discard=true){if(busy.value)return;busy.value=true;try{const id=pendingCanvas.value,result=await api(id==='main'?'diagram':'canvases/'+id);activeCanvas.value=id;diagramLayout.value=result.nodes;diagramVersion.value=result.version;diagramDirty.value=false;selectedAsset.value='';diagramZoom.value=1;setDiagramTool('select');if(discard)closeModal(true);}catch(e){message.value=e.message;}finally{busy.value=false;}}
function resetDiagram(){if(busy.value)return;diagramDrag.value=null;diagramConnect.value=null;diagramLayout.value=graphNodes.value.map((n,i)=>({id:n.id,x:60+(i%4)*245,y:60+Math.floor(i/4)*130}));diagramDirty.value=true;}
const impacts=computed(()=>{if(!selectedAsset.value)return [];const visited=new Set([selectedAsset.value]),queue=[selectedAsset.value];while(queue.length){const target=queue.shift();for(const r of relations.value.filter(r=>r.target_id===target&&['depends-on','hosts'].includes(r.type))){if(!visited.has(r.source_id)){visited.add(r.source_id);queue.push(r.source_id);}}}return [...visited].filter(id=>id!==selectedAsset.value);});
function devicesForSide(face){return rackDevices.value.filter(p=>p.full_depth!==false||(p.facing||'front')===face);}
function unitDevice(u,face='front'){return devicesForSide(face).find(p=>u>=p.start_unit&&u<p.start_unit+p.height);}
const draggedDevice=ref(null),dropPreview=ref(null);
function clearRackDrag(){draggedDevice.value=null;dropPreview.value=null;}
function startRackDrag(event,p,unit=p.start_unit){
 if(!can('update')||busy.value||!p){event.preventDefault();return;}
 draggedDevice.value={...p,offset:unit-p.start_unit};dropPreview.value=null;message.value='';
 event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('application/x-nist-rack-device',p.asset_id);
 event.dataTransfer.setData('text/plain',name(p.asset_id));
}
function rackMoveError(p,rackId,start){
 const target=racks.value.find(r=>r.id===rackId);
 if(!target||!Number.isInteger(start)||start<1||start+p.height-1>target.units)return 'Posisi perangkat melebihi kapasitas rak.';
 if(placements.value.some(x=>x.rack_id===rackId&&x.asset_id!==p.asset_id&&(p.full_depth!==false||x.full_depth!==false||(p.facing||'front')===(x.facing||'front'))&&start<x.start_unit+x.height&&x.start_unit<start+p.height))return 'Posisi U bertabrakan dengan perangkat lain.';
 return '';
}
function rackDropCandidate(rackId,unit,face){
 if(!draggedDevice.value)return null;const p={...draggedDevice.value,facing:face||draggedDevice.value.facing||'front'};
 let start=unit===undefined?1:unit-p.offset;
 if(unit===undefined){const target=racks.value.find(r=>r.id===rackId);while(target&&start+p.height-1<=target.units&&rackMoveError(p,rackId,start))start++;}
 return {rackId,startUnit:start,height:p.height,facing:p.facing,fullDepth:p.full_depth!==false,error:rackMoveError(p,rackId,start)};
}
function hoverRackDrop(event,rackId,unit,face){
 if(!draggedDevice.value||!can('update')||busy.value)return;
 event.preventDefault();const candidate=rackDropCandidate(rackId,unit,face);dropPreview.value=candidate;
 event.dataTransfer.dropEffect=candidate.error?'none':'move';
}
function dropRackDevice(event,rackId,unit,face){
 event.preventDefault();if(!draggedDevice.value||!can('update')||busy.value){clearRackDrag();return;}
 const p=draggedDevice.value,candidate=rackDropCandidate(rackId,unit,face);clearRackDrag();
 if(candidate.error){message.value=candidate.error;return;}
 if(p.rack_id===rackId&&p.start_unit===candidate.startUnit&&(p.facing||'front')===candidate.facing){message.value='Posisi perangkat tidak berubah.';return;}
 placement.value={originalAssetId:p.asset_id,previousRackId:p.rack_id,assetId:p.asset_id,rackId,startUnit:candidate.startUnit,height:p.height,facing:candidate.facing,fullDepth:candidate.fullDepth,changeReference:''};
 showModal('placement');
}
function rackUnitPreview(u,face='front'){const preview=dropPreview.value;return preview?.rackId===selectedRack.value&&(preview.fullDepth||preview.facing===face)&&u>=preview.startUnit&&u<preview.startUnit+preview.height?(preview.error?'drop-invalid':'drop-valid'):'';}

function rackBlockStyle(p){return {top:(rack.value.units-p.start_unit-p.height+1)*unitPixels+'px',height:p.height*unitPixels+'px'};}
function rackEventUnit(event){return rack.value.units-Math.floor((event.clientY-event.currentTarget.getBoundingClientRect().top)/unitPixels);}
function startBlockDrag(event,p){const rect=event.currentTarget.getBoundingClientRect();const row=Math.max(0,Math.min(p.height-1,Math.floor((event.clientY-rect.top)/unitPixels)));startRackDrag(event,p,p.start_unit+p.height-1-row);}
function photoUrl(kind,id,face){const photo=photoCatalog.value[kind]?.find(p=>p.owner_id===id&&p.side===face);if(!photo||failedPhotos.value.includes(photo.version))return '';return '/api/asset-management/photos/'+kind+'/'+id+'/'+face+'?v='+photo.version;}
function devicePhotoUrl(p,face){return photoUrl('assets',p.asset_id,face===(p.facing||'front')?'front':'rear');}
function photoFailed(kind,id,face){const photo=photoCatalog.value[kind]?.find(p=>p.owner_id===id&&p.side===face);if(photo)failedPhotos.value.push(photo.version);}
function clearPhotoPreviews(){if(photosEditor.value)for(const face of ['front','rear'])if(photosEditor.value[face].preview)URL.revokeObjectURL(photosEditor.value[face].preview);photosEditor.value=null;}
function editPhotos(kind,id){clearPhotoPreviews();photosEditor.value={kind,id,front:{file:null,preview:'',remove:false},rear:{file:null,preview:'',remove:false}};showModal('photos');}
async function selectPhoto(event,face){
 const file=event.target.files?.[0],value=photosEditor.value[face];message.value='';
 if(value.preview)URL.revokeObjectURL(value.preview);value.file=null;value.preview='';value.width=0;value.height=0;if(!file)return;
 if(file.size>5*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type)){message.value='Gunakan PNG, JPEG, atau WebP maksimum 5 MB.';event.target.value='';return;}
 photoReadCount.value++;const preview=URL.createObjectURL(file);let dimensions;try{dimensions=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve({width:img.naturalWidth,height:img.naturalHeight});img.onerror=reject;img.src=preview;}).finally(()=>photoReadCount.value--);}catch{URL.revokeObjectURL(preview);message.value='Foto tidak dapat dibaca.';event.target.value='';return;}
 if(photosEditor.value?.[face]!==value){URL.revokeObjectURL(preview);return;}value.file=file;value.preview=preview;value.width=dimensions.width;value.height=dimensions.height;value.remove=false;
}
function savePhotos(){if(photoReadCount.value)return;const e=photosEditor.value;perform(async()=>{const form=photoFormData(e);const r=await fetch('/api/asset-management/photos/'+e.kind+'/'+e.id,{method:'PUT',body:form});const result=await r.json();if(!r.ok)throw Error(result.error||'Unggah foto gagal.');closeModal(true);});}
async function assetTabKey(event,key){const keys=assetTabs.value.map(t=>t.key);let index=keys.indexOf(key);if(event.key==='ArrowRight')index=(index+1)%keys.length;else if(event.key==='ArrowLeft')index=(index+keys.length-1)%keys.length;else if(event.key==='Home')index=0;else if(event.key==='End')index=keys.length-1;else return;event.preventDefault();await open(keys[index]);await nextTick();document.querySelector('[data-asset-tab="'+keys[index]+'"]')?.focus();}
async function open(key){if(busy.value)return;clearRackDrag();closeModal(true);view.value=key;message.value='';document.querySelectorAll('.view').forEach(v=>v.classList.remove('active-view'));document.getElementById('assetManagementView')?.classList.add('active-view');document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===key));try{const s=JSON.parse(localStorage.getItem('nist-maturity-ui')||'{}');localStorage.setItem('nist-maturity-ui',JSON.stringify({...s,view:key}));}catch{}await load();}
function navigate(event){const key=event.target.closest('[data-view]')?.dataset.view;if(titles[key]){event.preventDefault();event.stopImmediatePropagation();open(key);}}
function restoreAssetView(){try{const key=JSON.parse(localStorage.getItem('nist-maturity-ui')||'{}').view;if(titles[key])open(key);}catch{}}
onMounted(()=>{document.addEventListener('click',navigate,true);window.addEventListener('vue:workspace-ready',restoreAssetView);if(document.documentElement?.dataset.frontend==='vue')restoreAssetView();});
onBeforeUnmount(()=>{window.removeEventListener('vue:workspace-ready',restoreAssetView);clearPhotoPreviews();modal.value?.close();document.removeEventListener('click',navigate,true);});
</script>
<template>
<section id="assetManagementView" class="view asset-management">
 <div class="page-heading"><div><p class="eyebrow">ASSET MANAGEMENT / ITSM</p><h2>{{titles[view]}}</h2><p class="lede">Inventaris, siklus hidup, lokasi fisik, dan relasi layanan dari satu register aset.</p></div><div class="csf-actions"><button v-if="transferAllowed('read')" class="button button-quiet" :disabled="busy" @click="exportAssets">Export JSON</button><button v-if="transferAllowed('create')&&transferAllowed('update')" class="button button-quiet" :disabled="busy" @click="transferInput.click()">Import JSON</button><input ref="transferInput" type="file" accept=".json,application/json" hidden @change="previewAssetImport"><button class="button button-quiet" :disabled="busy" @click="load">Muat ulang</button></div></div>
 <p class="muted" role="status" aria-live="polite">{{busy?'Memuat / menyimpan data…':message}}</p>
 <div class="risk-management-tabs asset-main-tabs" role="tablist" aria-label="Asset Management"><button v-for="tab in assetTabs" :key="tab.key" type="button" role="tab" :data-asset-tab="tab.key" :aria-selected="view===tab.key" :tabindex="view===tab.key?0:-1" :class="['button',view===tab.key?'button-accent':'button-quiet']" :disabled="busy" @click="open(tab.key)" @keydown="assetTabKey($event,tab.key)">{{tab.label}}</button></div>
 <article v-if="adDrill&&view!== 'asset-dashboard'&&view===({assets:'asset-register',racks:'server-racks',relations:'asset-modelling'}[adDrill.target])" class="insight-panel gd-list-context"><p class="muted" role="status">Filter dashboard: {{adDrill.label}} · {{adDrillIds.size}} data dalam cakupan dashboard.</p><div class="csf-actions"><button type="button" class="button button-quiet" :disabled="busy" @click="open('asset-dashboard')">Kembali ke dashboard</button><button type="button" class="button button-quiet" :disabled="busy" @click="adDrill=null">Hapus drill-down</button></div></article>
 <div v-if="view==='asset-dashboard'&&access[view]?.read" id="assetDashboardPanel" class="gd-dashboard asset-dashboard">
  <article class="insight-panel gd-controls"><div class="section-heading compact"><div><p class="eyebrow">ASSET INTELLIGENCE</p><h3>Inventaris, kapasitas &amp; pemodelan aset</h3></div><div class="csf-actions"><button id="adRefresh" type="button" class="button button-quiet" :disabled="busy" @click="load">Refresh data</button><button id="adAlertsButton" type="button" class="button button-quiet" :disabled="busy||!adFullAssets" :aria-expanded="adAlertsOpen" aria-controls="adAlerts" @click="adAlertsOpen=!adAlertsOpen">Renewal perlu perhatian <span class="file-count">{{adFullAssets?adAlerts.length:'-'}}</span></button><select id="adExport" v-model="adExportFormat" :disabled="busy||!adHasAssets" aria-label="Ekspor dashboard asset" @change="adExport"><option value="">Export laporan</option><option value="csv">CSV / Excel (aset)</option><option value="json">JSON (ringkasan modul)</option></select></div></div>
   <div class="rd-filters"><label>Jenis aset<select id="adType" v-model="adFilters.type" :disabled="busy||!adHasAssets"><option value="">Semua jenis</option><option v-for="type in types" :key="type" :value="type">{{type}}</option></select></label><label>Status aset<select id="adStatus" v-model="adFilters.status" :disabled="busy||!adHasAssets"><option value="">Semua status</option><option v-for="status in statuses" :key="status" :value="status">{{status}}</option></select></label><label>Pemilik<select id="adOwner" v-model="adFilters.owner" :disabled="busy||!adFullAssets"><option value="">Semua pemilik</option><option v-for="owner in adOwners" :key="owner" :value="owner" data-no-translate>{{owner}}</option></select></label><label>Lokasi<select id="adLocation" v-model="adFilters.location" :disabled="busy"><option value="">Semua lokasi</option><option v-for="location in adLocations" :key="location" :value="location" data-no-translate>{{location}}</option></select></label><label>Risiko CIA<select id="adRisk" v-model="adFilters.risk" :disabled="busy||!adFullAssets"><option value="">Semua risiko</option><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option><option value="unassessed">Belum dinilai</option></select></label><label>Jadwal renewal<select id="adRenewal" v-model="adFilters.renewal" :disabled="busy||!adFullAssets"><option value="">Semua jadwal</option><option value="soon">Dalam 30 hari</option><option value="overdue">Overdue</option><option value="missing">Tanpa tanggal</option></select></label><button id="adReset" type="button" class="button button-quiet" :disabled="busy" @click="resetAssetDashboard">Reset filter</button></div>
   <p class="muted gd-filter-status" role="status">{{adAssets.length}} / {{adData.assets.length}} aset · {{adRacks.length}} rak · {{adRelations.length}} relasi dalam cakupan.</p><div class="asset-dashboard-sources"><span v-for="source in [{key:'assets',label:'Asset Register'},{key:'racks',label:'Server Racks'},{key:'relations',label:'Relasi aset'},{key:'canvases',label:'Kanvas model'}]" :key="source.key" :class="['asset-source',adSources[source.key]]">{{source.label}}: {{({ready:'Tersedia',catalog:'Katalog terbatas',denied:'Tidak ada akses baca',error:'Gagal dimuat',partial:'Sebagian dimuat',idle:'Belum dimuat'})[adSources[source.key]]}}</span></div>
  </article>
  <article v-if="adAlertsOpen" id="adAlerts" class="insight-panel"><h3>Renewal perlu perhatian</h3><p class="muted">Berdasarkan tanggal renewal; retired/disposed dikecualikan. Pengiriman email tetap mengikuti pengaturan SMTP dan reminder aset yang sudah ada.</p><button v-for="a in adAlerts" :key="a.id" type="button" class="rd-alert" :data-ad-alert="a.id" :disabled="busy" @click="adOpenList('assets','record',a.id,a.tag+' - '+a.name)"><strong>{{a.tag}} · {{a.name}}</strong><small>{{a.owner||'Pemilik belum diisi'}} · {{a.renewalDate}} · {{days(a)<0?Math.abs(days(a))+' hari terlewat':days(a)===0?'Hari ini':days(a)+' hari lagi'}}</small></button><p v-if="!adAlerts.length" class="muted">Tidak ada renewal mendekat atau overdue dalam cakupan.</p></article>
  <div class="rd-kpis"><button v-for="metric in adKpis" :key="metric.target+metric.kind" type="button" :class="['stat-panel','rd-kpi',{'asset-dashboard-unavailable':!metric.available}]" :data-ad-kpi="metric.target+'-'+metric.kind" :disabled="busy||!metric.available||!access[({assets:'asset-register',racks:'server-racks',relations:'asset-modelling'}[metric.target])]?.read" @click="adOpenList(metric.target,metric.kind,'',metric.label)"><span class="stat-label">{{metric.label}}</span><strong>{{metric.value}}</strong><span class="stat-detail">{{metric.detail}}</span></button></div>
  <div class="gd-visuals"><article v-for="chart in adDistributions" :key="chart.key" class="insight-panel"><p class="eyebrow">ASSET DISTRIBUTION</p><h3>{{chart.title}}</h3><div class="rd-bars"><template v-if="chart.items"><button v-for="item in chart.items" :key="item.value" type="button" class="rd-bar" :data-ad-chart="chart.key" :data-ad-value="item.value" :disabled="busy||!access['asset-register']?.read" @click="adOpenList('assets',chart.key,item.value,chart.title+': '+item.label)"><span>{{item.label}}</span><strong>{{item.count}} <small>({{item.percent}}%)</small></strong><i><b :style="{width:item.width+'%'}"></b></i></button><p v-if="!chart.items.length" class="muted">Tidak ada aset sesuai filter.</p></template><p v-else class="muted">Memerlukan data lengkap dan akses baca Asset Register.</p></div></article></div>
  <div class="gd-visuals"><article class="insight-panel"><div class="section-heading compact"><div><p class="eyebrow">RACK CAPACITY</p><h3>Utilisasi Server Racks</h3></div><button type="button" class="button button-quiet" :disabled="busy||adSources.racks!=='ready'" @click="adOpenList('racks','all','','Rak dalam cakupan')">Buka rak</button></div><p class="muted">Posisi U unik pada rak terpilih, termasuk seluruh perangkat depan/belakang. Kapasitas tidak dibatasi hanya pada aset yang lolos filter.</p><div v-if="adSources.racks==='ready'&&adSources.placements==='ready'" class="rd-bars"><button v-for="r in adRacks" :key="r.id" type="button" class="rd-bar" :data-ad-rack="r.id" :disabled="busy" @click="adOpenList('racks','record',r.id,r.name)"><span>{{r.name}} <small>· {{r.location}} · {{adRackUsage(r).devices}} perangkat</small></span><strong>{{adRackUsage(r).used}} / {{r.units}} U ({{adRackUsage(r).percent}}%)</strong><i><b :class="{'ad-capacity-high':adRackUsage(r).percent>=85}" :style="{width:adRackUsage(r).percent+'%'}"></b></i></button><p v-if="!adRacks.length" class="muted">Tidak ada rak sesuai filter.</p></div><p v-else class="muted">Data rak dan penempatan belum tersedia atau memerlukan akses baca Server Racks.</p></article>
   <article class="insight-panel"><p class="eyebrow">MODELLING COVERAGE</p><h3>Cakupan model &amp; relasi</h3><p class="muted">Aset dianggap tercatat pada model jika terdapat pada node kanvas tersimpan atau menjadi ujung relasi. Perubahan kanvas yang belum disimpan tidak dihitung.</p><div v-if="adHasAssets&&adModelReady" class="rd-bars"><button type="button" class="rd-bar" data-ad-coverage="mapped" :disabled="busy||!access['asset-register']?.read" @click="adOpenList('assets','mapped','','Aset pada model')"><span>Aset pada model</span><strong>{{adMapped.length}}</strong><i><b :style="{width:(adAssets.length?adMapped.length/adAssets.length*100:0)+'%'}"></b></i></button><button type="button" class="rd-bar" data-ad-coverage="unmapped" :disabled="busy||!access['asset-register']?.read" @click="adOpenList('assets','unmapped','','Aset belum tercatat pada model')"><span>Belum tercatat pada model</span><strong>{{adAssets.length-adMapped.length}}</strong><i><b :style="{width:(adAssets.length?(adAssets.length-adMapped.length)/adAssets.length*100:0)+'%'}"></b></i></button></div><p v-else class="muted">Cakupan belum dapat dihitung sampai katalog aset, relasi, dan seluruh kanvas berhasil dimuat.</p><h3>Relasi per jenis</h3><div v-if="adSources.relations==='ready'" class="rd-bars"><button v-for="item in adRelationGroups" :key="item.value" type="button" class="rd-bar" :data-ad-relation="item.value" :disabled="busy" @click="adOpenList('relations','type',item.value,'Relasi: '+item.label)"><span>{{item.label}}</span><strong>{{item.count}}</strong><i><b :style="{width:item.width+'%'}"></b></i></button><p v-if="!adRelationGroups.length" class="muted">Tidak ada relasi yang melibatkan aset dalam cakupan.</p></div></article></div>
  <div class="gd-visuals"><article class="insight-panel"><div class="section-heading compact"><div><p class="eyebrow">RENEWAL CALENDAR</p><h3>Kalender renewal aset</h3></div><label>Bulan<input id="adMonth" v-model="adMonth" type="month" :disabled="busy||!adFullAssets"></label></div><template v-if="adFullAssets"><div class="ra-weekdays" aria-hidden="true"><span>Min</span><span>Sen</span><span>Sel</span><span>Rab</span><span>Kam</span><span>Jum</span><span>Sab</span></div><div class="ra-calendar"><template v-for="day in adCalendar" :key="day.id"><button v-if="day.date" type="button" :class="['ra-calendar-day',day.count?(day.remaining<0?'ra-day-overdue':day.remaining<=30?'ra-day-soon':'ra-day-scheduled'):'']" :data-ad-date="day.date" :aria-label="day.date+', '+day.count+' renewal'" :disabled="busy||!day.count" @click="adOpenList('assets','date',day.date,'Renewal: '+day.date)"><strong>{{day.day}}</strong><small v-if="day.count">{{day.count}} aset</small></button><span v-else aria-hidden="true"></span></template></div><p class="muted">Renewal aset aktif. Merah: overdue; kuning: hingga 30 hari. Klik tanggal untuk membuka daftar.</p></template><p v-else class="muted">Memerlukan data lengkap dan akses baca Asset Register.</p></article>
   <article class="insight-panel"><p class="eyebrow">RENEWAL SCHEDULE</p><h3>Renewal per bulan</h3><div v-if="adFullAssets" class="rd-bars"><button v-for="item in adRenewalTimeline" :key="item.value" type="button" class="rd-bar" :data-ad-month="item.value" :disabled="busy" @click="adOpenList('assets','month',item.value,'Renewal bulan: '+item.value)"><span>{{item.value}}</span><strong>{{item.count}}</strong><i><b :style="{width:item.width+'%'}"></b></i></button><p v-if="!adRenewalTimeline.length" class="muted">Belum ada jadwal renewal sesuai filter.</p></div><h3>Kanvas pemodelan</h3><div class="rd-bars"><button v-for="c in adData.canvases" :key="c.id" type="button" class="rd-bar" :data-ad-canvas="c.id" :disabled="busy||!c.available" @click="adOpenCanvas(c.id)"><span>{{c.name}}</span><strong>{{c.available?c.nodes.filter(n=>adAssetIds.has(n.id)).length+' node tersimpan':'Belum tersedia'}}</strong></button><p v-if="!adData.canvases.length" class="muted">Data kanvas belum tersedia atau memerlukan akses baca Modelling Asset Register.</p></div></article></div>
 </div>
 <template v-if="view==='asset-register' && access[view]?.read"><div class="risk-management-tabs" role="tablist" aria-label="Asset Register"><button type="button" role="tab" :aria-selected="registerTab==='assets'" :class="['button',registerTab==='assets'?'button-accent':'button-quiet']" :disabled="busy" @click="selectRegisterTab('assets')">Daftar aset</button><button type="button" role="tab" :aria-selected="registerTab==='reminder'" :class="['button',registerTab==='reminder'?'button-accent':'button-quiet']" :disabled="busy" @click="selectRegisterTab('reminder')">Pengaturan Email / SMTP</button></div><template v-if="registerTab==='assets'">
 <div class="risk-dashboard-grid asset-stats"><article class="stat-panel"><span class="stat-label">Aset terdaftar</span><strong>{{assets.length}}</strong><span class="stat-detail">Seluruh aset dalam register</span></article><article class="stat-panel"><span class="stat-label">Digunakan</span><strong>{{assets.filter(a=>a.status==='in-use').length}}</strong><span class="stat-detail">Aset operasional aktif</span></article><article class="stat-panel"><span class="stat-label">Perlu renewal</span><strong>{{dueAssets.length}}</strong><span class="stat-detail">Mendekati / lewat tanggal renewal</span></article></div>
 <p class="insight-panel muted asset-notice">Alur ITSM: Planned → In stock → In use ↔ Maintenance → Retired → Disposed. Referensi tiket/change bersifat opsional. Lepaskan relasi dan posisi rak sebelum retirement.</p>
 <div class="toolbar asset-toolbar"><label class="search-box"><span aria-hidden="true">/</span><input v-model="search" type="search" aria-label="Cari aset" placeholder="Cari tag, nama, pemilik, layanan..."></label><button v-if="can('create')" class="button button-accent" :disabled="busy" @click="editAsset()">+ Tambah aset</button></div>
 <div class="toolbar asset-toolbar asset-filter-bar" aria-label="Filter daftar aset"><label>Jenis<select v-model="assetFilters.type"><option value="">Semua jenis</option><option v-for="t in types" :key="t" :value="t">{{t}}</option></select></label><label>Status<select v-model="assetFilters.status"><option value="">Semua status</option><option v-for="t in statuses" :key="t" :value="t">{{t}}</option></select></label><label>Risiko CIA<select v-model="assetFilters.risk"><option value="">Semua risiko</option><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option><option value="unassessed">Belum dinilai</option></select></label><label>Renewal<select v-model="assetFilters.renewal"><option value="">Semua renewal</option><option value="overdue">Lewat tanggal</option><option value="due">Mendekati renewal</option><option value="undated">Tanpa tanggal</option></select></label><label>Pemilik<select v-model="assetFilters.owner"><option value="">Semua pemilik</option><option data-no-translate v-for="owner in assetOwners" :key="owner" :value="owner">{{owner}}</option></select></label><label>Vendor pengelola<select v-model="assetFilters.vendor"><option value="">Semua vendor</option><option value="unmanaged">Tanpa vendor pengelola</option><option v-for="v in assetVendorOptions" :key="v.id" :value="v.id">{{v.name}}</option></select></label><button type="button" class="button button-quiet" @click="resetAssetFilters">Reset filter</button><span class="muted" role="status">{{visibleAssets.length}} / {{assets.length}} aset</span></div>
 <div class="excel-wrap asset-table"><table class="excel-table asset-register-table"><thead><tr><th>Tag / aset</th><th>Jenis / layanan</th><th>Pemilik</th><th>Vendor pengelola</th><th>Status</th><th>Risiko CIA</th><th>Related risk</th><th>Renewal</th><th>Aksi</th></tr></thead><tbody><tr v-for="a in visibleAssets" :key="a.id"><td><strong data-no-translate>{{a.tag}}</strong><br>{{displayAssetName(a)}}<br><small>{{a.vendor}} {{a.model}}</small></td><td><span data-translate-ui>{{a.type}}</span><br>{{a.service||'—'}}</td><td>{{a.owner}}<br><small>{{a.ownerEmail}}</small></td><td><span v-if="a.managedVendorId">{{a.managedVendorName||'Vendor TPRM tidak tersedia'}}</span><span v-else class="muted">-</span></td><td data-translate-ui>{{a.status}}<br>{{a.criticality}}</td><td class="asset-list-risk"><template v-if="assessmentResult(a.assetAssessment)"><span :class="['risk-rating',assessmentResult(a.assetAssessment).level]">{{assessmentResult(a.assetAssessment).level.toUpperCase()}}</span><br><small data-translate-ui>Skor {{assessmentResult(a.assetAssessment).score}} / 25</small><br><small>C: {{a.assetAssessment.confidentiality}} | I: {{a.assetAssessment.integrity}} | A: {{a.assetAssessment.availability}}</small><br><small data-translate-ui>Dampak {{assessmentResult(a.assetAssessment).impact}} x kemungkinan {{a.assetAssessment.likelihood}}</small></template><span data-translate-ui v-else class="muted">Belum dinilai</span></td><td class="asset-related-risks"><strong data-translate-ui>{{(a.riskRegisterIds||[]).length}} related risk</strong><div class="asset-related-risk-actions"><button v-if="can('update')" type="button" class="button button-quiet" :disabled="busy||!riskAccess" @click="openAssetRisks(a,true)">Pilih risk</button><button type="button" class="button button-quiet" :disabled="busy||!riskAccess" @click="openAssetRisks(a)">Lihat related risk</button></div><div v-if="riskCatalogAvailable" class="asset-related-risk-counts"><span v-for="count in relatedRiskCounts(a)" :key="count.level" :class="['risk-rating',count.css]">{{count.level}}: {{count.count}}</span></div><small v-else class="muted">{{riskAccess?'Risk Register belum dapat dimuat.':'Memerlukan akses baca Risk Register.'}}</small></td><td :class="{'asset-warning':days(a)!==null&&days(a)<=a.reminderDays}">{{a.renewalDate||'—'}}<br><small data-translate-ui v-if="days(a)!==null">{{days(a)<0?'Lewat '+Math.abs(days(a))+' hari':days(a)+' hari lagi'}}</small><br><small data-translate-ui>{{a.reminderEnabled?'Email aktif · H-'+a.reminderDays:'Email nonaktif'}}</small></td><td><button v-if="can('update')" class="button button-quiet" :disabled="busy" @click="editAsset(a)">Ubah</button><button v-if="can('delete')" class="button button-danger" :disabled="busy" @click="remove('assets',a.id)">Hapus</button></td></tr><tr v-if="!visibleAssets.length"><td colspan="9">Belum ada aset yang sesuai. Tambahkan aset untuk mulai mengelola rak dan relasi.</td></tr></tbody></table></div>
 <p class="muted">Reminder dikirim ke email pemilik menggunakan SMTP terpusat. Pemeriksaan setiap jam; maksimal satu email per aset, tanggal renewal, dan penerima per hari, termasuk renewal yang terlambat. Server harus berjalan.</p>
 </template><article v-if="registerTab==='reminder'" class="insight-panel"><div class="section-heading"><h3>Pengaturan email renewal aset</h3><button v-if="reminderSettings&&can('update')" class="button button-accent" :disabled="busy" @click="editReminder()">Ubah pengaturan</button></div><p class="muted">Pilih akun SMTP yang tersedia dari Pengaturan SMTP terpusat. Jadwal H- dan penerima tetap mengikuti pengaturan masing-masing aset.</p><template v-if="reminderSettings"><p><strong>Akun SMTP:</strong> {{reminderSettings.smtpAccounts.find(a=>a.id===reminderSettings.smtpAccountId)?.name||reminderSettings.smtpAccountId}} - {{reminderSettings.smtpConfigured?'Siap digunakan':'Belum dikonfigurasi'}}</p><p><strong>Subjek:</strong> {{reminderSettings.subjectTemplate}}</p><pre class="asset-email-preview">{{reminderSettings.bodyTemplate}}</pre></template></article>
 </template>
 <template v-if="view==='server-racks' && access[view]?.read">
 <div class="toolbar asset-toolbar asset-filter-bar" aria-label="Filter daftar rak"><label>Cari rak<input v-model="rackSearch" type="search" placeholder="Nama, lokasi, atau kapasitas rak"></label><label>Lokasi<select v-model="rackLocationFilter"><option value="">Semua lokasi</option><option data-no-translate v-for="location in rackLocations" :key="location" :value="location">{{location}}</option></select></label><button type="button" class="button button-quiet" @click="resetRackFilters">Reset filter</button><span class="muted" role="status">{{filteredRacks.length}} / {{racks.length}} rak</span></div>
 <div class="toolbar asset-toolbar"><select v-model="selectedRack" aria-label="Pilih rak"><option value="">Pilih rak</option><option v-for="r in rackOptions" :key="r.id" :value="r.id">{{r.name}} · {{r.location}} · {{r.units}}U</option></select><button v-if="can('create')" class="button button-accent" :disabled="busy" @click="editRack()">+ Tambah rak</button><button v-if="rack&&can('update')" class="button button-accent" :disabled="busy" @click="editPlacement()">+ Pasang perangkat</button><button v-if="rack&&can('update')" class="button button-quiet" @click="editRack(rack)">Ubah rak</button><button v-if="rack&&can('delete')" class="button button-danger" :disabled="busy" @click="remove('racks',rack.id)">Hapus rak</button></div>
 <p v-if="can('update')" class="muted">Seret perangkat ke posisi U tujuan. Untuk memindahkan antar rak, jatuhkan pada kartu rak tujuan; slot kosong dipilih otomatis dan dapat diubah di modal konfirmasi.</p>
 <div v-if="can('update') && racks.length>1" class="asset-rack-targets" aria-label="Rak tujuan pemindahan"><button v-for="r in filteredRacks" :key="r.id" type="button" :class="['button button-quiet rack-drop-target',{'drop-valid':dropPreview?.rackId===r.id&&!dropPreview.error,'drop-invalid':dropPreview?.rackId===r.id&&dropPreview.error}]" :disabled="busy" @click="selectedRack=r.id;dropPreview=null" @dragover="hoverRackDrop($event,r.id)" @dragleave="dropPreview=null" @drop.stop="dropRackDevice($event,r.id)">{{r.name}} · {{r.units}}U<span v-if="dropPreview?.rackId===r.id">{{dropPreview.error||('Tujuan U'+dropPreview.startUnit+'-U'+(dropPreview.startUnit+dropPreview.height-1))}}</span></button></div>
 <p v-if="dropPreview" class="muted" role="status">{{dropPreview.error||('Pindahkan ke U'+dropPreview.startUnit+'-U'+(dropPreview.startUnit+dropPreview.height-1))}}</p>
 <template v-if="rack"><div class="risk-management-tabs" role="tablist" aria-label="Rak Server"><button type="button" role="tab" :aria-selected="rackTab==='elevation'" :class="['button',rackTab==='elevation'?'button-accent':'button-quiet']" :disabled="busy" @click="rackTab='elevation';clearRackDrag()">Tampilan rak</button><button type="button" role="tab" :aria-selected="rackTab==='devices'" :class="['button',rackTab==='devices'?'button-accent':'button-quiet']" :disabled="busy" @click="rackTab='devices';clearRackDrag()">Perangkat terpasang ({{rackDevices.length}})</button></div>
 <div class="toolbar asset-toolbar"><div><strong>{{rack.name}}</strong><span class="muted"> · {{rack.location}} · {{usedUnits}} / {{rack.units}} U terpakai</span></div><label class="rack-images-toggle"><input v-model="showRackImages" type="checkbox"> Tampilkan foto perangkat</label><button v-if="can('update')" class="button button-quiet" :disabled="busy" @click="editPhotos('racks',rack.id)">Foto rak depan / belakang</button></div>
 <div v-if="rackTab==='elevation'" class="rack-dual-elevation">
 <article v-for="face in faces" :key="face.id" class="insight-panel rack-elevation"><div class="section-heading compact"><h3>{{face.label}}</h3><span class="file-count">{{rack.units}}U</span></div>
 <div class="rack-frame" :style="{height:rack.units*unitPixels+'px'}" @dragover="hoverRackDrop($event,selectedRack,rackEventUnit($event),face.id)" @drop.stop="dropRackDevice($event,selectedRack,rackEventUnit($event),face.id)">
 <div v-for="u in Array.from({length:rack.units},(_,i)=>rack.units-i)" :key="u" :class="['rack-slot',rackUnitPreview(u,face.id)]" :style="{height:unitPixels+'px'}"><span class="rack-unit-number">{{u}}</span><span class="rack-slot-space"></span><span class="rack-unit-number">{{u}}</span></div>
 <button v-for="p in devicesForSide(face.id)" :key="p.asset_id" type="button" :class="['rack-device-block',{'reverse-face':(p.facing||'front')!==face.id,'is-dragging':draggedDevice?.asset_id===p.asset_id}]" :style="rackBlockStyle(p)" :draggable="can('update')&&!busy" :disabled="busy" :aria-label="name(p.asset_id)+' '+face.label+' U'+p.start_unit+'-'+(p.start_unit+p.height-1)" :title="name(p.asset_id)+' · '+p.height+'U · '+face.label" @click="can('update')&&editPlacement(p)" @dragstart="startBlockDrag($event,p)" @dragend="clearRackDrag">
 <template v-if="showRackImages&&devicePhotoUrl(p,face.id)"><span data-no-translate class="rack-photo-name">{{name(p.asset_id)}}</span><img :src="devicePhotoUrl(p,face.id)" :alt="name(p.asset_id)+' '+face.label" draggable="false" @error="photoFailed('assets',p.asset_id,face.id===(p.facing||'front')?'front':'rear')"></template><span v-else class="rack-device-label"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="M6 8h12M6 12h12M6 16h8"/></svg><strong data-no-translate>{{name(p.asset_id)}}</strong><small v-if="p.height>1">{{p.height}}U · {{assets.find(a=>a.id===p.asset_id)?.tag}}</small></span>
 </button></div>
 <details v-if="photoUrl('racks',rack.id,face.id)" class="rack-reference-photo"><summary>Foto rak {{face.label.toLowerCase()}}</summary><img :src="photoUrl('racks',rack.id,face.id)" :alt="rack.name+' '+face.label" @error="photoFailed('racks',rack.id,face.id)"></details>
 </article></div>
 <template v-if="rackTab==='devices'"><div class="toolbar asset-toolbar asset-filter-bar" aria-label="Filter perangkat terpasang"><label>Cari perangkat<input v-model="deviceSearch" type="search" placeholder="Nama, tag, atau posisi U"></label><label>Orientasi<select v-model="deviceFacingFilter"><option value="">Semua orientasi</option><option value="front">Depan</option><option value="rear">Belakang</option></select></label><label>Kedalaman<select v-model="deviceDepthFilter"><option value="">Semua kedalaman</option><option value="full">Full depth</option><option value="single">Satu sisi</option></select></label><button type="button" class="button button-quiet" @click="resetDeviceFilters">Reset filter</button><span class="muted" role="status">{{filteredRackDevices.length}} / {{rackDevices.length}} perangkat</span></div><div class="section-heading"><div><p class="eyebrow">RACK DEVICES</p><h3>Perangkat terpasang</h3></div></div><div class="excel-wrap"><table class="excel-table"><thead><tr><th>Perangkat</th><th>Posisi / tinggi</th><th>Orientasi / kedalaman</th><th>Aksi</th></tr></thead><tbody><tr v-for="p in filteredRackDevices" :key="p.asset_id" :draggable="can('update')&&!busy" @dragstart="startRackDrag($event,p)" @dragend="clearRackDrag"><td>{{name(p.asset_id)}}</td><td>U{{p.start_unit}}-U{{p.start_unit+p.height-1}} · {{p.height}}U</td><td data-translate-ui>{{p.facing==='rear'?'Belakang':'Depan'}} · {{p.full_depth===false?'Satu sisi':'Full depth'}}</td><td><button v-if="can('update')" class="button button-quiet" :disabled="busy" @click="editPlacement(p)">Ubah posisi</button><span class="muted">Foto dari Asset Register</span><button v-if="can('delete')" class="button button-quiet" :disabled="busy" @click="remove('placements',p.asset_id)">Lepaskan</button></td></tr><tr v-if="!filteredRackDevices.length"><td colspan="4">Tidak ada perangkat yang cocok dengan filter.</td></tr></tbody></table></div></template>
 </template><p v-else>Daftarkan rak terlebih dahulu, lalu pilih perangkat dari Asset Register.</p>
 </template>
 <template v-if="view==='asset-modelling' && access[view]?.read"><div class="risk-management-tabs" role="tablist" aria-label="Modelling Asset Register"><button type="button" role="tab" :aria-selected="modellingTab==='canvas'" :class="['button',modellingTab==='canvas'?'button-accent':'button-quiet']" :disabled="busy" @click="modellingTab='canvas';diagramDrag=null;diagramConnect=null">Kanvas arsitektur</button><button type="button" role="tab" :aria-selected="modellingTab==='relations'" :class="['button',modellingTab==='relations'?'button-accent':'button-quiet']" :disabled="busy" @click="modellingTab='relations';diagramDrag=null;diagramConnect=null;diagramConnectionSource=''">Daftar relasi ({{relations.length}})</button></div>
 <details class="insight-panel asset-relation-guide"><summary>Panduan relasi dan dependensi langsung / tidak langsung</summary><p>Panah dibaca dari sumber ke tujuan. Jenis relasi menentukan maknanya; arah panah tidak selalu menunjukkan arah dampak gangguan.</p><div class="asset-relation-guide-grid"><article><h4>Direct / langsung</h4><p>Aset bergantung pada aset terpilih melalui satu relasi depends-on atau hosts. Contoh: Aplikasi -> Database. Jika Database dipilih, Aplikasi bergantung langsung.</p></article><article><h4>Indirect / tidak langsung</h4><p>Aset bergantung melalui perantara, dua relasi atau lebih. Contoh: Portal -> API -> Database. Jika Database dipilih, API bergantung langsung dan Portal bergantung tidak langsung.</p></article></div><p>Analisis ketergantungan hanya menelusuri depends-on dan hosts menuju aset terpilih, termasuk beberapa tingkat. connects-to, protects, balances, dan backs-up tidak otomatis masuk perhitungan. Hasil menunjukkan potensi dampak; redundansi dan failover perlu dinilai terpisah.</p><div class="asset-relation-guide-grid"><article v-for="type in relationTypes" :key="type"><h4><code data-no-translate>{{type}}</code></h4><p>{{relationExplanation(type)}}</p></article></div></details>
 <template v-if="modellingTab==='canvas'"><div class="toolbar asset-toolbar asset-canvas-selector"><label>Kanvas aktif<select :value="activeCanvas" :disabled="busy" @change="changeCanvas($event.target.value);$event.target.value=activeCanvas"><option v-for="c in canvases" :key="c.id" :value="c.id" data-no-translate>{{c.name}}</option></select></label><button v-if="can('create')" type="button" class="button button-accent" :disabled="busy||diagramDirty" @click="editCanvas()">+ Tambah kanvas</button><button v-if="can('update')&&activeCanvas!=='main'" type="button" class="button button-quiet" :disabled="busy" @click="editCanvas(true)">Ubah nama kanvas</button><small v-if="diagramDirty" class="muted">Simpan perubahan sebelum menambah kanvas.</small></div><div class="toolbar asset-toolbar"><label>Analisis ketergantungan <select v-model="selectedAsset"><option value="">Pilih aset</option><option v-for="a in assets" :key="a.id" :value="a.id">{{a.tag}} · {{displayAssetName(a)}}</option></select></label></div><p v-if="selectedAsset">Aset yang bergantung langsung/tidak langsung: {{impacts.map(name).join(', ')||'Tidak ada dependensi tercatat.'}}</p>
 <div class="toolbar asset-toolbar"><div class="asset-canvas-tools" role="group" aria-label="Alat kanvas"><button type="button" :class="['button asset-canvas-tool',diagramTool==='select'?'button-accent':'button-quiet']" title="Pilih / pindahkan aset" aria-label="Pilih / pindahkan aset" :aria-pressed="diagramTool==='select'" :disabled="busy" @click="setDiagramTool('select')"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 3l14 10-7 1-3 7z"/></svg></button><button v-if="can('create')" type="button" :class="['button asset-canvas-tool',diagramTool==='connect'?'button-accent':'button-quiet']" title="Hubungkan aset" aria-label="Hubungkan aset" :aria-pressed="diagramTool==='connect'" :disabled="busy" @click="setDiagramTool('connect')"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="2" y="3" width="6" height="6" rx="1"/><rect x="16" y="15" width="6" height="6" rx="1"/><path d="M8 6h5v12h3m-3-3 3 3-3 3"/></svg></button></div><button type="button" class="button button-quiet" :disabled="diagramZoom<=.4" @click="diagramZoom=Math.max(.4,diagramZoom-.1)">-</button><span>{{Math.round(diagramZoom*100)}}%</span><button type="button" class="button button-quiet" :disabled="diagramZoom>=2" @click="diagramZoom=Math.min(2,diagramZoom+.1)">+</button><button type="button" class="button button-quiet" @click="diagramZoom=1">100%</button><button v-if="can('update')" type="button" class="button button-quiet" :disabled="busy" @click="resetDiagram()">Susun otomatis</button><button v-if="can('update')" type="button" class="button button-accent" :disabled="busy||!diagramDirty" @click="showModal('diagram-save')">Simpan diagram</button><button type="button" class="button button-quiet" :disabled="busy" @click="showModal('diagram-reload')">Muat ulang diagram</button><button type="button" class="button button-quiet" :disabled="busy||diagramExporting||!graphNodes.length" @click="exportDiagramImage('png')">Export PNG</button><button type="button" class="button button-quiet" :disabled="busy||diagramExporting||!graphNodes.length" @click="exportDiagramImage('svg')">Export SVG</button><span class="muted" role="status">{{diagramDirty?'Posisi belum disimpan':'Posisi tersimpan'}}</span></div>
 <p class="muted">Seret aset dari katalog ke kanvas. Gunakan ikon Pilih untuk memindahkan kartu. Pilih ikon Hubungkan, lalu klik aset sumber dan tujuan; atau seret titik koneksi ke kartu tujuan. Jenis relasi dikonfirmasi melalui modal. Gunakan scroll untuk menjelajahi kanvas.</p>
 <p v-if="diagramTool==='connect'" class="insight-panel muted" role="status">{{diagramConnectionSource?'Sumber: '+name(diagramConnectionSource)+'. Klik aset tujuan untuk menghubungkan.':'Klik aset sumber, kemudian klik aset tujuan.'}} <button type="button" class="button button-quiet" @click="setDiagramTool('select')">Batal / kembali ke Pilih</button></p><div class="asset-modelling-workbench"><aside class="insight-panel asset-diagram-palette"><h3>Katalog aset</h3><input v-model="diagramAssetSearch" @input="diagramPalettePage=1" type="search" placeholder="Cari aset..." aria-label="Cari aset diagram"><select v-model="diagramTypeFilter" @change="diagramPalettePage=1" aria-label="Filter jenis aset diagram"><option value="">Semua jenis</option><option v-for="t in types" :key="t" :value="t">{{t}}</option></select><p class="muted asset-palette-count" role="status">{{diagramPalette.length?((currentPalettePage-1)*diagramPalettePageSize+1)+'?'+Math.min(currentPalettePage*diagramPalettePageSize,diagramPalette.length):0}} / {{diagramPalette.length}} aset</p><div class="asset-palette-items"><button v-for="a in pagedDiagramPalette" :key="a.id" type="button" class="button button-quiet asset-diagram-palette-item" :draggable="can('update')&&!busy" :disabled="busy||!can('update')" @dragstart="diagramPaletteDrag($event,a)" @click="requestDiagramNode(a.id)"><strong data-no-translate>{{a.tag}}</strong><span data-no-translate>{{displayAssetName(a)}}</span><small>{{a.type}} - {{graphNodes.some(n=>n.id===a.id)?'Di kanvas':'Seret ke kanvas'}}</small></button><p v-if="!diagramPalette.length" class="muted">Tidak ada aset yang sesuai.</p></div><nav v-if="diagramPalettePages>1" class="asset-palette-pagination" aria-label="Halaman katalog aset"><button type="button" class="button button-quiet" :disabled="busy||currentPalettePage===1" aria-label="Katalog aset: halaman sebelumnya" @click="diagramPalettePage=currentPalettePage-1">&#8249;</button><span aria-live="polite">{{currentPalettePage}} / {{diagramPalettePages}}</span><button type="button" class="button button-quiet" :disabled="busy||currentPalettePage===diagramPalettePages" aria-label="Katalog aset: halaman berikutnya" @click="diagramPalettePage=currentPalettePage+1">&#8250;</button></nav></aside>
 <div class="insight-panel asset-graph" @dragover.prevent @drop="dropDiagramAsset($event)"><svg ref="diagramSvg" :viewBox="`0 0 ${graphWidth} ${graphHeight}`" :style="{width:graphWidth*diagramZoom+'px',height:graphHeight*diagramZoom+'px'}" role="img" aria-label="Kanvas interaktif relasi arsitektur aset" :class="{'is-connecting':diagramTool==='connect'}" @keydown.esc="setDiagramTool('select')" @pointermove="moveDiagramPointer($event)" @pointerup="finishDiagramPointer($event)" @pointercancel="diagramDrag=null;diagramConnect=null"><defs><marker id="assetArrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0L10 5L0 10Z" class="asset-arrow"/></marker><pattern id="assetGrid" width="20" height="20" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="#cad5e2"/></pattern></defs><rect :width="graphWidth" :height="graphHeight" fill="url(#assetGrid)"/><g v-for="r in canvasRelations" :key="r.id" :data-diagram-relation="r.id"><title>{{name(r.source_id)}} - {{r.type}} - {{name(r.target_id)}}</title><path :d="diagramEdgePath(r)" fill="none" class="asset-edge" stroke-width="2" marker-end="url(#assetArrow)"/><text :x="diagramEdgeGeometry(r).labelX" :y="diagramEdgeGeometry(r).labelY" text-anchor="middle" class="asset-edge-label" font-size="12">{{r.type}}</text></g><path v-if="diagramConnect" :d="`M${point(diagramConnect.sourceId).x+190},${point(diagramConnect.sourceId).y+29} L${diagramConnect.x},${diagramConnect.y}`" class="asset-edge" fill="none" stroke-width="2" stroke-dasharray="5 4"/><g v-for="a in graphNodes" :key="a.id" :data-diagram-asset="a.id" tabindex="0" role="button" :aria-label="'Aset '+a.name" @pointerdown="startDiagramNode($event,a)" @keydown.enter.prevent="chooseDiagramAsset(a)"><rect :x="a.x" :y="a.y" width="190" height="58" rx="9" :class="['asset-node',{selected:selectedAsset===a.id,'connection-source':diagramConnectionSource===a.id}]"/><text data-no-translate :x="a.x+12" :y="a.y+23" class="asset-node-title" font-size="13">{{a.tag.slice(0,24)}}</text><text data-no-translate :x="a.x+12" :y="a.y+43" class="asset-node-detail" font-size="12" :textLength="displayAssetName(a).length>24?166:undefined" lengthAdjust="spacingAndGlyphs">{{displayAssetName(a)}}</text><circle v-if="can('create')" :cx="a.x+190" :cy="a.y+29" r="7" class="asset-connection-port" @pointerdown="startDiagramConnection($event,a)"><title>Seret ke aset tujuan untuk menambah relasi</title></circle><title>{{displayAssetName(a)}} ({{a.type}})</title></g></svg><p v-if="!graphNodes.length" class="asset-diagram-empty">Seret aset terdaftar dari katalog untuk mulai membuat arsitektur.</p></div></div>
 </template><div v-if="modellingTab==='relations'" class="toolbar asset-toolbar asset-filter-bar" aria-label="Filter daftar relasi"><label>Cari relasi<input v-model="relationSearch" type="search" placeholder="Sumber, tujuan, catatan, atau change"></label><label>Jenis relasi<select v-model="relationTypeFilter"><option value="">Semua relasi</option><option v-for="t in relationTypes" :key="t" :value="t">{{t}}</option></select></label><label>Aset terkait<select v-model="relationAssetFilter"><option value="">Semua aset</option><option v-for="a in assets" :key="a.id" :value="a.id">{{a.tag}} - {{displayAssetName(a)}}</option></select></label><button type="button" class="button button-quiet" @click="resetRelationFilters">Reset filter</button><span class="muted" role="status">{{filteredRelations.length}} / {{relations.length}} relasi</span></div><div v-if="modellingTab==='relations'" class="excel-wrap asset-table"><table class="excel-table"><thead><tr><th>Sumber</th><th>Relasi</th><th>Tujuan</th><th>Change / catatan</th><th>Aksi</th></tr></thead><tbody><tr v-for="r in filteredRelations" :key="r.id"><td>{{name(r.source_id)}}</td><td data-translate-ui>{{r.type}}</td><td>{{name(r.target_id)}}</td><td>{{r.change_reference}}<br>{{r.notes}}</td><td><button v-if="can('update')" class="button button-quiet" :disabled="busy" @click="editRelation(r)">Ubah</button><button v-if="can('delete')" class="button button-danger" :disabled="busy" @click="remove('relations',r.id)">Hapus</button></td></tr><tr v-if="!filteredRelations.length"><td colspan="5">Tidak ada relasi yang cocok dengan filter.</td></tr></tbody></table></div>
 </template>
 <dialog ref="modal" class="certification-modal asset-modal" aria-labelledby="assetModalTitle" aria-describedby="assetModalStatus" @cancel="cancelModal">
 <div class="section-heading compact"><div><p class="eyebrow">ASSET MANAGEMENT</p><h3 id="assetModalTitle">{{modalTitle}}</h3></div><button type="button" class="button button-quiet" aria-label="Tutup modal" :disabled="busy" @click="closeModal()">Tutup</button></div>
 <p id="assetModalStatus" class="muted" role="status" aria-live="polite">{{busy?'Menyimpan perubahan...':message}}</p>
<form v-if="modalKind==='risks-edit' && riskLinkAsset" class="risk-register-form asset-form" @submit.prevent="saveAssetRisks"><p><strong>{{displayAssetName(riskLinkAsset)}}</strong> - pilih risiko dari Risk Register yang sudah terdaftar.</p><div class="toolbar asset-toolbar"><input v-model="riskPickerSearch" type="search" placeholder="Cari risk ID, perangkat, risiko..." aria-label="Cari related risk"><select v-model="riskPickerCategory" aria-label="Filter kategori risiko"><option value="">Semua kategori</option><option v-for="value in [...new Set(riskCatalog.map(r=>r.riskCategory).filter(Boolean))]" :key="value" :value="value">{{value}}</option></select><select v-model="riskPickerRating" aria-label="Filter rating risiko"><option value="">Semua rating</option><option v-for="value in ['Very Low','Low','Medium','High','Very High']" :key="value" :value="value">{{value}}</option></select><select v-model="riskPickerTreatment" aria-label="Filter treatment"><option value="">Semua treatment</option><option v-for="value in [...new Set(riskCatalog.map(r=>r.treatmentAction).filter(Boolean))]" :key="value" :value="value">{{value}}</option></select></div><p role="status">{{riskSelection.length}} risiko dipilih</p><div class="excel-wrap"><table class="excel-table asset-risk-picker-table"><thead><tr><th>Pilih</th><th>Risk ID</th><th>Risk Category</th><th>Affected Asset / Perangkat</th><th>Identification Risk</th><th>Risk Rating</th><th>Residual Rating</th></tr></thead><tbody><tr v-for="r in visibleRiskRows" :key="r.riskId"><td><input v-model="riskSelection" type="checkbox" :value="r.riskId" :aria-label="'Pilih '+r.riskId"></td><td>{{r.riskId}}</td><td>{{r.riskCategory}}</td><td>{{r.effectedAsset}}<br>{{r.deviceName}}</td><td>{{r.identificationRisk}}</td><td><span :class="['risk-rating',r.riskRating?.toLowerCase().replaceAll(' ','-')]">{{r.riskRating||'-'}}</span></td><td><span :class="['risk-rating',r.residualRating?.toLowerCase().replaceAll(' ','-')]">{{r.residualRating||'-'}}</span></td></tr><tr v-if="!visibleRiskRows.length"><td colspan="7">Tidak ada risiko yang sesuai.</td></tr></tbody></table></div><div class="toolbar asset-toolbar"><button type="button" class="button button-quiet" :disabled="riskPickerPage<=1" @click="riskPickerPage=Math.max(1,Math.min(riskPickerPage,riskPickerPageCount)-1)">Sebelumnya</button><span>Halaman {{Math.min(riskPickerPage,riskPickerPageCount)}} / {{riskPickerPageCount}}</span><button type="button" class="button button-quiet" :disabled="riskPickerPage>=riskPickerPageCount" @click="riskPickerPage=Math.min(riskPickerPageCount,riskPickerPage+1)">Berikutnya</button></div><div class="csf-form-actions"><button class="button button-accent" :disabled="busy">Simpan related risk</button><button type="button" class="button button-quiet" :disabled="busy" @click="closeModal()">Batal</button></div></form>
<div v-if="modalKind==='risks-view' && riskLinkAsset" class="asset-risk-details"><div v-if="relatedRiskRows(riskLinkAsset).length" class="excel-wrap"><table class="excel-table"><thead><tr><th v-for="column in riskColumns()" :key="column.key">{{column.label}}</th></tr></thead><tbody><tr v-for="r in relatedRiskRows(riskLinkAsset)" :key="r.riskId"><td v-for="column in riskColumns()" :key="column.key"><span v-if="['riskRating','residualRating'].includes(column.key)" :class="['risk-rating',r[column.key]?.toLowerCase().replaceAll(' ','-')]">{{r[column.key]||'-'}}</span><template v-else>{{r[column.key]||'-'}}</template></td></tr></tbody></table></div><p v-else class="muted">Belum ada related risk yang dipilih untuk aset ini.</p><div class="csf-form-actions"><button type="button" class="button button-quiet" @click="closeModal()">Tutup</button></div></div>
<form v-if="modalKind==='import'&&pendingTransfer" class="risk-register-form asset-form" @submit.prevent="importAssets"><p>Import {{pendingTransfer.assets}} aset, {{pendingTransfer.racks}} rak, {{pendingTransfer.placements}} penempatan, {{pendingTransfer.relations}} relasi, dan {{pendingTransfer.photos}} foto dari {{transferFile?.name}}?</p><p class="muted">Aset dengan tag yang sama dan rak dengan nama yang sama akan diperbarui. Record lain tetap tersimpan. Posisi rak, foto, dan diagram dari file akan diterapkan. Vendor TPRM dan Related risk harus tersedia. File import juga masuk Uploaded Files. Maksimal 100 MB.</p><div class="csf-form-actions"><button class="button button-accent" :disabled="busy">Import data</button><button type="button" class="button button-quiet" :disabled="busy" @click="closeModal()">Batal</button></div></form>
<form v-if="modalKind==='canvas-editor'" class="risk-register-form asset-form" @submit.prevent="saveCanvasDetails"><label>Nama kanvas<input v-model="canvasEditor.name" maxlength="150" required :disabled="busy" placeholder="Contoh: Arsitektur Data Center"></label><p v-if="!canvasEditor.id" class="muted">Kanvas baru dimulai kosong. Aset yang sama dapat digunakan pada beberapa kanvas dengan posisi berbeda. Relasi ditampilkan jika kedua aset ada di kanvas.</p><div class="csf-form-actions"><button class="button button-accent" :disabled="busy">Simpan</button><button type="button" class="button button-quiet" :disabled="busy" @click="closeModal()">Batal</button></div></form><form v-if="modalKind==='canvas-switch'" class="risk-register-form asset-form" @submit.prevent="applyCanvasSwitch()"><p>Perubahan posisi belum disimpan. Pindah kanvas dan buang perubahan ini?</p><div class="csf-form-actions"><button class="button button-danger" :disabled="busy">Buang perubahan dan pindah</button><button type="button" class="button button-quiet" :disabled="busy" @click="closeModal()">Batal</button></div></form>
<form v-if="modalKind==='diagram-reload'" class="risk-register-form asset-form" @submit.prevent="reloadDiagram"><p>Muat ulang posisi diagram dari server? Perubahan posisi yang belum disimpan akan dibuang.</p><div class="csf-form-actions"><button class="button button-accent" :disabled="busy">Muat ulang</button><button type="button" class="button button-quiet" :disabled="busy" @click="closeModal()">Batal</button></div></form><form v-if="modalKind==='diagram-node' && pendingDiagramNode" class="risk-register-form asset-form" @submit.prevent="confirmDiagramNode"><p>Tambahkan {{name(pendingDiagramNode.id)}} ke kanvas pada posisi {{pendingDiagramNode.x}}, {{pendingDiagramNode.y}}?</p><div class="csf-form-actions"><button class="button button-accent" :disabled="busy">Tambahkan</button><button type="button" class="button button-quiet" @click="closeModal()">Batal</button></div></form><form v-if="modalKind==='diagram-save'" class="risk-register-form asset-form" @submit.prevent="saveDiagram"><p>Simpan posisi {{graphNodes.length}} aset dalam diagram arsitektur?</p><div class="csf-form-actions"><button class="button button-accent" :disabled="busy">Simpan</button><button type="button" class="button button-quiet" :disabled="busy" @click="closeModal()">Batal</button></div></form>
<form v-if="modalKind==='reminder' && reminderEditor" class="risk-register-form asset-form" @submit.prevent="saveReminder"><label>Akun SMTP<select v-model="reminderEditor.smtpAccountId" required><option v-for="account in reminderSettings.smtpAccounts" :key="account.id" :value="account.id">{{account.name}} - {{account.configured?'Siap digunakan':'Belum dikonfigurasi'}}</option></select></label><label>Subjek email<input v-model="reminderEditor.subjectTemplate" required maxlength="250"></label><label>Pesan email<textarea v-model="reminderEditor.bodyTemplate" required maxlength="10000" rows="12"></textarea></label><p class="muted">Placeholder: <code v-text="'{{tag}}, {{name}}, {{owner}}, {{ownerEmail}}, {{service}}, {{renewalDate}}, {{vendor}}, {{model}}, {{location}}'"></code></p><div class="csf-form-actions"><button class="button button-accent" :disabled="busy">Simpan pengaturan</button><button type="button" class="button button-quiet" :disabled="busy" @click="closeModal()">Batal</button></div></form>
<form v-if="modalKind==='editor' && editor" class="risk-register-form asset-form" @submit.prevent="save"><template v-if="editor.kind==='assets'"><div class="risk-register-grid asset-fields"><label v-for="key in ['tag','name','owner','ownerEmail','serial','vendor','model','location','service','changeReference']" :key="key">{{({tag:'Asset tag',name:'Nama aset',owner:'Pemilik / penanggung jawab',ownerEmail:'Email pemilik',serial:'Serial number',vendor:'Vendor',model:'Model',location:'Lokasi',service:'Layanan bisnis',changeReference:'Referensi change/tiket (opsional)'})[key]}}<input v-model="editor.data[key]" :type="key==='ownerEmail'?'email':'text'" :required="['tag','name','owner'].includes(key)" :maxlength="key==='ownerEmail'?254:150"></label><label>Jenis<select v-model="editor.data.type"><option v-for="t in types" :key="t" :value="t">{{t}}</option></select></label><label>Status siklus hidup<select v-model="editor.data.status"><option v-for="s in statuses" :key="s" :value="s">{{s}}</option></select></label><label>Vendor pengelola TPRM (opsional)<select v-model="editor.data.managedVendorId" aria-label="Vendor pengelola TPRM (opsional)" :disabled="busy||!vendorCatalogAvailable"><option value="">Tidak dikelola vendor</option><option v-if="editor.data.managedVendorId&&!managedVendors.some(v=>v.id===editor.data.managedVendorId)" :value="editor.data.managedVendorId">{{editor.data.managedVendorName||'Vendor TPRM tidak tersedia'}}</option><option v-for="v in managedVendors" :key="v.id" :value="v.id">{{v.name}}{{v.service?' - '+v.service:''}} ({{v.status}})</option></select><small v-if="!vendorCatalogAvailable" class="muted">{{vendorAccess?'Daftar vendor TPRM belum dapat dimuat.':'Memerlukan akses baca TPRM untuk memilih vendor.'}}</small></label><label>Kritikalitas<select v-model="editor.data.criticality"><option v-for="c in ['low','medium','high','critical']" :key="c" :value="c">{{c}}</option></select></label><label v-for="key in ['purchaseDate','renewalDate','warrantyDate']" :key="key">{{({purchaseDate:'Tanggal pembelian',renewalDate:'Tanggal renewal',warrantyDate:'Akhir garansi'})[key]}}<input v-model="editor.data[key]" type="date"></label><label>Reminder mulai H-<input v-model.number="editor.data.reminderDays" type="number" min="0" max="365" required></label></div><fieldset class="asset-cia-assessment"><legend>Assessment risiko aset (CIA)</legend><p class="muted">Nilai dampak jika kerahasiaan, keutuhan, atau ketersediaan aset terganggu.</p><div class="excel-wrap"><table class="excel-table"><thead><tr><th>Confidentiality</th><th>Integrity</th><th>Availability</th></tr></thead><tbody><tr><td v-for="key in ['confidentiality','integrity','availability']" :key="key"><select v-model.number="editor.data.assetAssessment[key]" :aria-label="key" required><option value="">Pilih dampak</option><option :value="1">Sangat rendah (1)</option><option :value="2">Rendah (2)</option><option :value="3">Sedang (3)</option><option :value="4">Tinggi (4)</option><option :value="5">Sangat tinggi (5)</option></select></td></tr></tbody></table></div><label>Kemungkinan kejadian<select v-model.number="editor.data.assetAssessment.likelihood" aria-label="Kemungkinan kejadian" required><option value="">Pilih kemungkinan</option><option :value="1">Sangat jarang (1)</option><option :value="2">Jarang (2)</option><option :value="3">Mungkin (3)</option><option :value="4">Sering (4)</option><option :value="5">Sangat sering (5)</option></select></label><p role="status" class="asset-cia-result"><strong>Risiko otomatis:</strong> <span v-if="currentAssetAssessment" :class="['risk-rating',currentAssetAssessment.level]">{{currentAssetAssessment.level.toUpperCase()}}</span><span v-else>Lengkapi CIA dan kemungkinan kejadian.</span><small v-if="currentAssetAssessment"> Dampak {{currentAssetAssessment.impact}} x kemungkinan {{editor.data.assetAssessment.likelihood}} = {{currentAssetAssessment.score}}</small></p><p class="muted">Dampak = nilai CIA tertinggi. Skor 1-4: Low, 5-12: Medium, 15-25: High.</p><details><summary>Matriks risiko 5 x 5</summary><div class="excel-wrap asset-risk-matrix-wrap"><table class="excel-table asset-risk-matrix"><thead><tr><th>Kemungkinan / Dampak</th><th>Sangat rendah (1)</th><th>Rendah (2)</th><th>Sedang (3)</th><th>Tinggi (4)</th><th>Sangat tinggi (5)</th></tr></thead><tbody><tr v-for="likelihood in [5,4,3,2,1]" :key="likelihood"><th>{{['','Sangat jarang','Jarang','Mungkin','Sering','Sangat sering'][likelihood]}} ({{likelihood}})</th><td data-translate-ui v-for="impact in [1,2,3,4,5]" :key="impact" :class="['asset-matrix-cell',likelihood*impact<=4?'low':likelihood*impact<=12?'medium':'high',{'is-selected':currentAssetAssessment?.impact===impact&&editor.data.assetAssessment.likelihood===likelihood} ]">{{likelihood*impact<=4?'Low':likelihood*impact<=12?'Medium':'High'}} ({{likelihood*impact}})</td></tr></tbody></table></div></details></fieldset><label><input v-model="editor.data.reminderEnabled" type="checkbox"> Aktifkan reminder email renewal</label><label>Deskripsi<textarea v-model="editor.data.description" maxlength="2000"></textarea></label><fieldset v-if="photosEditor" class="asset-photo-fields"><legend>Foto perangkat depan / belakang</legend><p class="muted">Foto disimpan bersama aset dan otomatis ditampilkan setelah perangkat ditempatkan di rak, sesuai orientasi serta tinggi U. Foto mengikuti proporsi asli dan tidak diperbesar melebihi resolusinya; ruang kosong dapat tersisa di blok perangkat. Gunakan foto panel yang tajam dengan lebar minimal 1200 piksel untuk tampilan rak yang jelas. File asli disimpan tanpa kompresi ulang. PNG, JPEG, WebP, maksimum 5 MB per sisi.</p><div class="rack-photo-editor"><div v-for="face in faces" :key="face.id"><label>Foto {{face.label.toLowerCase()}}<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="busy" @change="selectPhoto($event,face.id)"></label><img v-if="!photosEditor[face.id].remove && (photosEditor[face.id].preview||photoUrl('assets',editor.data.id,face.id))" :src="photosEditor[face.id].preview||photoUrl('assets',editor.data.id,face.id)" :alt="'Foto perangkat '+face.label"><p v-if="photosEditor[face.id].width" class="muted">{{photosEditor[face.id].width}} x {{photosEditor[face.id].height}} piksel<span v-if="photosEditor[face.id].width<1200"> - resolusi rendah; gunakan foto lebih besar untuk tampilan lebih besar di rak.</span></p><label v-if="photoUrl('assets',editor.data.id,face.id)"><input v-model="photosEditor[face.id].remove" type="checkbox" :disabled="busy||!!photosEditor[face.id].file"> Hapus foto {{face.label.toLowerCase()}}</label></div></div><p v-if="photoReadCount" class="muted" role="status">Membaca foto...</p></fieldset></template><template v-else><label>Nama rak<input v-model="editor.data.name" maxlength="150" required></label><label>Lokasi<input v-model="editor.data.location" maxlength="250" required></label><label>Kapasitas (U)<input v-model.number="editor.data.units" type="number" min="1" max="60" required></label></template><div class="csf-form-actions"><button class="button button-accent" :disabled="busy||photoReadCount>0">Simpan</button><button type="button" class="button button-quiet" :disabled="busy" @click="closeModal()">Batal</button></div></form>
<form v-if="modalKind==='placement'" class="risk-register-form asset-form" @submit.prevent="install"><label>Rak tujuan<select v-model="placement.rackId" required><option v-for="r in racks" :key="r.id" :value="r.id">{{r.name}} · {{r.location}}</option></select></label><label v-if="!placement.originalAssetId" style="grid-column:1/-1">Cari aset terdaftar<input id="placementAssetSearch" v-model="placementAssetSearch" type="search" placeholder="Cari nama, tag, jenis perangkat, atau rak..." autocomplete="off" :disabled="busy"></label><label v-if="!placement.originalAssetId">Jenis perangkat<select v-model="placementTypeFilter"><option value="">Semua jenis perangkat</option><option v-for="t in types.filter(t=>!['Software','License','Cloud'].includes(t))" :key="t" :value="t">{{t}}</option></select></label><label>Aset terdaftar<select v-model="placement.assetId" :disabled="!!placement.originalAssetId" :aria-invalid="!!placementSelectionError" aria-describedby="placementAssetStatus" required><option value="">Pilih perangkat</option><option v-for="a in placementAssets" :key="a.id" :value="a.id">{{a.tag}} · {{displayAssetName(a)}} - {{assetRackRemark(a.id)}}</option></select><small v-if="!placement.originalAssetId" role="status">{{placementAssets.length?placementAssets.length+' aset tersedia dalam daftar':'Tidak ada aset yang cocok dengan pencarian.'}}</small></label><p id="placementAssetStatus" :class="placementSelectionError?'asset-warning':'muted'" :role="placementSelectionError?'alert':'status'">{{placementSelectionError||(placement.assetId?assetRackRemark(placement.assetId):'Pilih perangkat yang belum dipasang.')}}</p><label>U awal (dari bawah)<input v-model.number="placement.startUnit" type="number" min="1" :max="racks.find(r=>r.id===placement.rackId)?.units||60" required></label><label>Tinggi perangkat (U)<input v-model.number="placement.height" type="number" min="1" :max="racks.find(r=>r.id===placement.rackId)?.units||60" required></label><label>Orientasi pemasangan<select v-model="placement.facing"><option value="front">Menghadap depan</option><option value="rear">Menghadap belakang</option></select></label><label><input v-model="placement.fullDepth" type="checkbox"> Full depth (memakai U pada kedua sisi rak)</label><label>Referensi change/tiket (opsional)<input v-model="placement.changeReference" maxlength="250"></label><div class="csf-form-actions"><button class="button button-accent" :disabled="busy||!!placementSelectionError">Simpan posisi</button><button type="button" class="button button-quiet" :disabled="busy" @click="closeModal()">Batal</button></div><p class="muted">Aset hanya memiliki satu posisi fisik. Pemasangan baru hanya untuk aset yang belum terpasang. Gunakan Ubah posisi atau drag-and-drop untuk memindahkan perangkat. Slot bertabrakan ditolak.</p></form>
<form v-if="modalKind==='relation'" class="risk-register-form asset-form" @submit.prevent="addRelation"><p v-if="relationFromCanvas" class="insight-panel"><strong>Sumber:</strong> {{name(relation.sourceId)}}<br><strong>Tujuan:</strong> {{name(relation.targetId)}}</p><label v-if="!relationFromCanvas">Aset sumber<select v-model="relation.sourceId" required><option value="">Pilih aset</option><option v-for="a in activeAssets" :key="a.id" :value="a.id">{{a.tag}} · {{displayAssetName(a)}}</option></select></label><label>Relasi<select v-model="relation.type" aria-describedby="assetRelationExplanation"><option v-for="t in relationTypes" :key="t" :value="t">{{t}}</option></select></label><p id="assetRelationExplanation" class="insight-panel muted asset-relation-explanation">{{relationExplanation(relation.type)}}</p><label v-if="!relationFromCanvas">Aset tujuan<select v-model="relation.targetId" required><option value="">Pilih aset</option><option v-for="a in activeAssets.filter(a=>a.id!==relation.sourceId)" :key="a.id" :value="a.id">{{a.tag}} · {{displayAssetName(a)}}</option></select></label><label>Referensi change/tiket (opsional)<input v-model="relation.changeReference" maxlength="250"></label><label>Catatan<input v-model="relation.notes" maxlength="1000"></label><div class="csf-form-actions"><button class="button button-accent" :disabled="busy">Simpan relasi</button><button type="button" class="button button-quiet" :disabled="busy" @click="closeModal()">Batal</button></div></form>
 <form v-if="modalKind==='remove'" class="risk-register-form asset-form" @submit.prevent="confirmRemoval"><p>{{pendingRemoval?.kind==='placements'?'Lepaskan perangkat dari rak?':'Hapus data ini?'}}</p><p class="muted">Relasi dan perangkat yang masih digunakan harus dilepas terlebih dahulu. Perubahan dicatat pada audit trail.</p><div class="csf-form-actions"><button class="button button-danger" :disabled="busy">{{pendingRemoval?.kind==='placements'?'Lepaskan':'Hapus'}}</button><button type="button" class="button button-quiet" :disabled="busy" @click="closeModal()">Batal</button></div></form>
<form v-if="modalKind==='photos' && photosEditor" class="risk-register-form asset-form" @submit.prevent="savePhotos"><p class="muted">{{photosEditor.kind==='assets'?'Foto panel perangkat mengikuti proporsi asli dan diperkecil bila perlu agar muat dalam ruang perangkat, tanpa pembesaran. Gunakan foto panel yang sudah dipotong untuk hasil terbaik.':'Foto keseluruhan rak ditampilkan sebagai referensi di bawah tampilan depan / belakang.'}} PNG, JPEG, WebP · maksimum 5 MB per sisi.</p><div class="rack-photo-editor"><div v-for="face in faces" :key="face.id"><label>Foto {{face.label.toLowerCase()}}<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="busy" @change="selectPhoto($event,face.id)"></label><img v-if="!photosEditor[face.id].remove && (photosEditor[face.id].preview||photoUrl(photosEditor.kind,photosEditor.id,face.id))" :src="photosEditor[face.id].preview||photoUrl(photosEditor.kind,photosEditor.id,face.id)" :alt="'Pratinjau '+face.label"><label v-if="photoUrl(photosEditor.kind,photosEditor.id,face.id)"><input v-model="photosEditor[face.id].remove" type="checkbox" :disabled="busy||!!photosEditor[face.id].file"> Hapus foto {{face.label.toLowerCase()}}</label></div></div><div class="csf-form-actions"><button class="button button-accent" :disabled="busy||photoReadCount>0">Simpan foto</button><button class="button button-quiet" type="button" :disabled="busy" @click="closeModal()">Batal</button></div></form>
